import sys
from openpyxl import load_workbook

path = sys.argv[1]
wb = load_workbook(path, data_only=True)

for ws in wb.worksheets:
    print(f"=== Sheet: {ws.title} | dims: {ws.dimensions} ===")
    for row in ws.iter_rows():
        vals = [f"{c.coordinate}={c.value!r}" for c in row if c.value is not None]
        if vals:
            print(" | ".join(vals))

# Heuristic column totals per sheet
for ws in wb.worksheets:
    headers = {}
    for c in ws[1]:
        if c.value is not None:
            headers[c.column] = str(c.value).strip().lower()
    target_col = None
    for col, h in headers.items():
        if any(k in h for k in ("expense", "amount", "cost", "budget", "actual", "spent", "total")):
            target_col = col
            break
    if target_col is None:
        print(f"[{ws.title}] no obvious amount column from headers: { {c:v for c,v in headers.items()} }")
        continue
    total = 0.0
    for row in ws.iter_rows(min_row=2, min_col=target_col, max_col=target_col):
        v = row[0].value
        if isinstance(v, (int, float)):
            total += v
    print(f"[{ws.title}] sum of column {ws.cell(1, target_col).coordinate} ({ws.cell(1, target_col).value!r}) data rows = {total:,.2f}")

